// Reads ngc output from stdin; for each "file(line,col): error TS2339: Property 'disableTooltip' does not exist on type 'X'"
// where X is a Pill component, rename the identifier at that exact position.
const fs = require('fs');
const out = fs.readFileSync(0, 'utf8');
const re = /([^\s:]+\.(?:ts|html))[:(](\d+)[:,](\d+)\)?:? - error TS2339: Property 'disableTooltip' does not exist on type '(\w+)'/g;
let m, n = 0; const edits = {};
while ((m = re.exec(out))) {
  if (!/^(PillComponent|FancyPillComponent|StatusPillComponent)$/.test(m[4])) { console.log('skip', m[0]); continue; }
  (edits[m[1]] ??= []).push([+m[2], +m[3]]);
}
for (const [f, list] of Object.entries(edits)) {
  const lines = fs.readFileSync(f, 'utf8').split('\n');
  for (const [l, c] of list) {
    const L = lines[l - 1];
    if (L.substr(c - 1, 14) !== 'disableTooltip') { console.log('mismatch', f, l, c, L); continue; }
    lines[l - 1] = L.slice(0, c - 1) + 'hideHint' + L.slice(c - 1 + 14); n++;
  }
  fs.writeFileSync(f, lines.join('\n'));
}
console.log('fixed', n);

